.settings {
  max-inline-size: 40rem;
  margin-inline: auto;
  padding: calc(var(--va-space-inline-lg) * 2) var(--va-space-inline-lg);
  font-family: var(--va-font-family-ui);
  color: var(--va-color-text-default);
}

.settings h1 {
  font-family: var(--va-font-family-reading);
  font-weight: var(--va-font-weight-bold);
  margin: 0;
}

.settings__header {
  margin-block-end: var(--va-space-inline-lg);
}

.settings__intro,
.settings__lead {
  color: var(--va-color-text-muted);
  margin: var(--va-space-inline-xs) 0 0;
}

.settings__panel {
  padding-block: var(--va-space-inline-lg);
}

.settings__form {
  display: grid;
  gap: var(--va-space-inline-lg);
  margin-block-start: var(--va-space-inline-lg);
}

.settings__actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--va-space-inline-sm);
}

.settings__list {
  list-style: none;
  margin: var(--va-space-inline-lg) 0 0;
  padding: 0;
  border: 1px solid var(--va-color-border-subtle);
  border-radius: var(--va-radius-surface);
  background: var(--va-color-surface-subtle);
}

.settings__list > li {
  padding: var(--va-space-inline-md) var(--va-space-inline-lg);
}

.settings__list > li + li {
  border-block-start: 1px solid var(--va-color-border-subtle);
}

js:
const STORAGE_KEY = 'settings';
const toaster = document.getElementById('toaster');

function load() {
  try {
    return JSON.parse(localStorage.getItem(STORAGE_KEY)) ?? {};
  } catch {
    return {};
  }
}

function save(data) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
  } catch {
    /* Storage unavailable: the setting still applies for this visit. */
  }
}

const stored = load();

// Switches: restore saved state, then apply and save each change straight away.
for (const toggle of document.querySelectorAll('va-switch[data-setting]')) {
  const key = toggle.dataset.setting;
  if (typeof stored[key] === 'boolean') toggle.checked = stored[key];

  toggle.addEventListener('change', (event) => {
    const on = event.target.checked;
    stored[key] = on;
    save(stored);
    toaster.show(`${toggle.dataset.label} turned ${on ? 'on' : 'off'}`);
  });
}

// Profile form: restore saved values; validate and save on submit.
const form = document.getElementById('profile-form');
const fields = form.querySelectorAll('va-text-field[name]');
const profile = stored.profile ?? {};

for (const field of fields) {
  if (typeof profile[field.name] === 'string') field.value = profile[field.name];
}

form.addEventListener('submit', (event) => {
  event.preventDefault();
  const invalid = [...fields].filter((field) => !field.checkValidity());
  if (invalid.length) {
    invalid[0].reportValidity();
    return;
  }
  stored.profile = Object.fromEntries([...fields].map((field) => [field.name, field.value]));
  save(stored);
  toaster.show('Profile saved');
});
